// revenueConversionHook.js
// Hook to record paid events on checkout success.
// Called by the checkout completion endpoint.

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', 'data', 'revenue_events.log');

function recordPaidEvent(amount, currency, userId, orderId) {
  const event = {
    type: 'paid',
    amount,
    currency: currency || 'USD',
    userId: userId || 'anonymous',
    orderId,
    timestamp: new Date().toISOString()
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  // Also increment in-memory counter if available
  if (global.__revenueCounters) {
    global.__revenueCounters.paidEvents = (global.__revenueCounters.paidEvents || 0) + 1;
  }
  return true;
}

module.exports = { recordPaidEvent };
